"""数据目录与集合配置。"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path

DEFAULT_DATA_DIR = Path(".readdesk")
DATABASE_NAME = "readdesk"
COLLECTION_NAME = "readdesk_chunks"
EMBEDDING_DIM = 512


@dataclass(frozen=True)
class Settings:
    """全局运行配置：只依赖 data_dir，其余路径按约定派生。"""

    data_dir: Path = field(default_factory=lambda: DEFAULT_DATA_DIR.resolve())
    database: str = DATABASE_NAME
    collection: str = COLLECTION_NAME
    dimension: int = EMBEDDING_DIM

    @classmethod
    def resolve(cls, data_dir: str | os.PathLike[str] | None = None) -> "Settings":
        """优先级：显式参数 > 环境变量 READDESK_DATA_DIR > 默认 ./.readdesk。"""
        if data_dir is None:
            data_dir = os.environ.get("READDESK_DATA_DIR") or DEFAULT_DATA_DIR
        return cls(data_dir=Path(data_dir).expanduser().resolve())

    @property
    def db_path(self) -> Path:
        """嵌入式 seekdb 的数据目录。"""
        return self.data_dir / "seekdb"

    @property
    def briefs_dir(self) -> Path:
        """简报输出目录。"""
        return self.data_dir / "briefs"

    def ensure(self) -> None:
        """创建数据目录结构。"""
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.briefs_dir.mkdir(parents=True, exist_ok=True)

"""通用小工具：哈希、tag 字段名、slug。"""

from __future__ import annotations

import hashlib
import re

_UNSAFE = re.compile(r"[^0-9A-Za-z_\u4e00-\u9fff]")


def sha256_bytes(data: bytes) -> str:
    """返回字节串的 sha256 十六进制。"""
    return hashlib.sha256(data).hexdigest()


def sha256_file(path) -> str:
    """返回文件内容的 sha256 十六进制。"""
    return sha256_bytes(path.read_bytes())


def tag_field(tag: str) -> str:
    """把标签映射为 seekdb metadata 的安全字段名，如 user-study -> tag_user_study。"""
    safe = _UNSAFE.sub("_", tag.strip().lower())
    safe = re.sub(r"_+", "_", safe).strip("_")
    return f"tag_{safe}" if safe else "tag_"


def normalize_tag(tag: str) -> str:
    """标签规范化：小写、去首尾空白。"""
    return tag.strip().lower()


def split_list_value(raw: str) -> list[str]:
    """解析 `[a, b]` 或 `a, b`（支持中文逗号），返回去空字符串列表。"""
    text = raw.strip()
    if text.startswith("[") and text.endswith("]"):
        text = text[1:-1]
    parts = re.split(r"[,，]", text)
    return [p.strip().strip("\"'""'' ") for p in parts if p.strip().strip("\"'""'' ")]


def slugify(text: str, max_len: int = 40) -> str:
    """把主题转为文件名 slug，保留中文。"""
    slug = _UNSAFE.sub("-", text.strip().lower())
    slug = re.sub(r"-+", "-", slug).strip("-")
    return slug[:max_len] if slug else "brief"

